import { execFileSync } from 'node:child_process';
import { closeSync, openSync, readdirSync, readFileSync, readSync } from 'node:fs';
import { availableParallelism, freemem, loadavg, totalmem } from 'node:os';
import { StringDecoder } from 'node:string_decoder';
import { defaultServerTestTimeoutMs } from './server-test-arguments.mjs';

/** Loaded by the node:test runner from the repository root, like the preloads. */
export const serverTestProgressReporter = './scripts/lib/server-test-progress-reporter.mjs';

/**
 * How long a running test file may report nothing before the watchdog ends it: one full --test-timeout, which
 * node:test enforces only inside a test, plus a minute. Null runs unwatched: `--test-timeout=0` or a forwarded
 * --inspect lets a debugger pause as long as it needs, a forwarded --test-reporter leaves no room for the watchdog's
 * own reporter (node:test pairs reporters with destinations), Windows has no ps to find a stuck file's process, and
 * before Node 24.20.0 node:test does not say which file a test belongs to (`entryFile`).
 */
export const serverTestStallMs = (forwarded, platform = process.platform, version = process.versions.node) => {
  const [major, minor] = version.split('.').map(Number);
  if (major < 24 || (major === 24 && minor < 20) || platform === 'win32'
    || forwarded.some(argument => argument.startsWith('--inspect') || argument.startsWith('--test-reporter'))) {
    return null;
  }
  const index = forwarded.findLastIndex(argument => argument.startsWith('--test-timeout'));
  const value = index < 0 ? defaultServerTestTimeoutMs : Number(forwarded[index].split('=')[1] ?? forwarded[index + 1]);
  return value > 0 ? value + 60_000 : null;
};

/** Keeps spec on stdout, which node:test drops once any reporter is named, and adds the progress reporter. */
export const serverTestProgressArguments = (progressPath, reporter = serverTestProgressReporter) => [
  '--test-reporter=spec', '--test-reporter-destination=stdout', `--test-reporter=${reporter}`, `--test-reporter-destination=${progressPath}`
];

const capture = (command, args) => {
  try { return execFileSync(command, args, { encoding: 'utf8', timeout: 10_000, stdio: ['ignore', 'pipe', 'pipe'] }); }
  catch (error) { return `(${command} ${args.join(' ')}: ${String(error.message).split('\n')[0]})\n`; }
};

/** The runner and every process below it, parents first; a node:test file process's last argument is its file. */
const processTree = runnerPid => {
  const rows = capture('ps', ['-ww', '-A', '-o', 'pid=,ppid=,stat=,etime=,args=']).split('\n')
    .map(line => /^\s*(\d+)\s+(\d+)\s+(\S+)\s+(\S+)\s+(.*)$/.exec(line)).filter(Boolean)
    .map(([, pid, ppid, stat, etime, args]) => ({ pid: Number(pid), ppid: Number(ppid), stat, etime, args }));
  const tree = rows.filter(row => row.pid === runnerPid);
  for (let index = 0; index < tree.length; index++) tree.push(...rows.filter(row => row.ppid === tree[index].pid));
  return tree;
};
const subtree = (tree, pid) => {
  const below = tree.filter(row => row.pid === pid);
  for (let index = 0; index < below.length; index++) below.push(...tree.filter(row => row.ppid === below[index].pid));
  return below;
};

/**
 * Linux: each thread's name, state and kernel wait channel; under GitHub Actions, whose runners allow passwordless
 * sudo, each thread's kernel stack too. Which threads are still present tells how far a stuck process got.
 */
const threadStates = pid => {
  if (process.platform !== 'linux') return '';
  let tids;
  try { tids = readdirSync(`/proc/${pid}/task`); } catch { return '  (process already gone)\n'; }
  return tids.map(tid => {
    const read = name => { try { return readFileSync(`/proc/${pid}/task/${tid}/${name}`, 'utf8').trim(); } catch { return '?'; } };
    const stack = process.env.GITHUB_ACTIONS === 'true' ? capture('sudo', ['-n', 'cat', `/proc/${pid}/task/${tid}/stack`]).replace(/^(?=.)/gm, '    ') : '';
    return `  thread ${tid} ${read('comm')} state=${read('stat').replace(/^.*\) /, '').split(' ')[0]} wchan=${read('wchan')}\n${stack}`;
  }).join('');
};

/**
 * node:test bounds a test with --test-timeout but never a test file's process: one blocked before its first test,
 * inside a synchronous or native call, or while exiting keeps the runner waiting forever, and the spec reporter then
 * holds back every later file's results. The watchdog follows the progress reporter's events; when a running file
 * has reported nothing for `stallMs`, it names the file and what it last reported, prints the process tree and thread
 * states, and kills that file's processes so node:test fails the file, prints the results it held and finishes the
 * run. The run then fails; nothing is retried. A hang it cannot end, such as a stuck runner, is left to CI's time
 * limits, after the same report. A file's process sends its reports asynchronously, so one that blocks inside a
 * synchronous test may never send its last ones: the counts are what reached the runner, and the threads are the
 * evidence of where it stopped.
 */
export const watchServerTests = ({ runner, progressPath, stallMs, pollMs = 2_000, log = console.error }) => {
  const running = new Map();
  const decoder = new StringDecoder('utf8');
  let offset = 0;
  let pending = '';
  let stalled = false;

  const readEvents = () => {
    let descriptor;
    try { descriptor = openSync(progressPath, 'r'); } catch { return; }
    try {
      const buffer = Buffer.alloc(64 * 1024);
      for (let bytes; (bytes = readSync(descriptor, buffer, 0, buffer.length, offset)) > 0; offset += bytes) {
        pending += decoder.write(buffer.subarray(0, bytes));
      }
    } finally { closeSync(descriptor); }
    const lines = pending.split('\n');
    pending = lines.pop();
    const now = Date.now();
    for (const { type, file, test } of lines.map(line => JSON.parse(line))) {
      if (!test) {
        if (type === 'test:dequeue') running.set(file, { startedAt: now, lastAt: now, last: 'its process started', finished: 0 });
        else running.delete(file);
      } else if (running.has(file)) {
        const state = running.get(file);
        Object.assign(state, { lastAt: now, last: `"${test}" ${type === 'test:complete' ? 'finished' : 'started'}` });
        if (type === 'test:complete') state.finished++;
      }
    }
  };

  const report = (summary, tree, focus) => {
    stalled = true;
    log(process.env.GITHUB_ACTIONS === 'true' ? `::error title=Server tests stalled::${summary}` : summary);
    log(`CPUs ${availableParallelism()}, load ${loadavg().map(value => value.toFixed(2)).join(' ')}, free memory ${Math.round(freemem() / 2 ** 20)} of ${Math.round(totalmem() / 2 ** 20)} MiB`);
    for (const row of tree) log(`${row.pid} ppid=${row.ppid} ${row.stat} ${row.etime} ${row.args.length > 160 ? `${row.args.slice(0, 40)} … ${row.args.slice(-100)}` : row.args}`);
    for (const row of focus) log(`Threads of ${row.pid}:\n${threadStates(row.pid)}`.trimEnd());
  };
  const kill = rows => { for (const row of [...rows].reverse()) { try { process.kill(row.pid, 'SIGKILL'); } catch { /* Already gone. */ } } };
  const seconds = at => Math.round((Date.now() - at) / 1_000);

  const timer = setInterval(() => {
    readEvents();
    const stuck = [...running].filter(([, state]) => !state.endedAt && Date.now() - state.lastAt > stallMs);
    if (!stuck.length) return;
    const tree = processTree(runner.pid);
    const processes = stuck.map(([file]) => subtree(tree, tree.find(row => row.ppid === runner.pid && row.args.endsWith(` ${file}`))?.pid));
    const names = stuck.map(([file, state], index) => `${file} (running ${seconds(state.startedAt)} s, reported tests finished: `
      + `${state.finished}, silent ${seconds(state.lastAt)} s since ${state.last}${processes[index].length ? '' : '; no process found for it'})`);
    // Without a process to blame, every thread in the tree is evidence, including a runner stuck starting the file.
    report(`Server test file stalled: ${names.join('; ')}. Ending its processes so node:test fails the file.`, tree,
      processes.flat().length ? processes.flat() : tree);
    for (const [, state] of stuck) state.endedAt = Date.now();
    processes.forEach(kill);
  }, pollMs);
  timer.unref();

  return { stop: () => clearInterval(timer), get stalled() { return stalled; } };
};
